APP_NAME = 'INVENTARIOS_IPSICOL'
REGIONALES = ('Bogotá', 'Cundinamarca')
UBICACIONES = ('REDENTOR', 'CIPLA', 'CAJICA', 'ESMERALDA')
MAX_FILE = 5 * 1024 * 1024
MAX_QTY = 2_000_000_000
BOGOTA = ZoneInfo('America/Bogota')
# Serialización de escrituras entre todas las instancias. El bloqueo vive solo
# durante la transacción, jamás mientras se espera una respuesta del usuario.
WRITE_LOCK = 74632019

SCHEMA_SQL = r'''
BEGIN;
CREATE SCHEMA IF NOT EXISTS ipsicol;
REVOKE ALL ON SCHEMA ipsicol FROM PUBLIC;
CREATE TABLE IF NOT EXISTS ipsicol.version (id int PRIMARY KEY CHECK(id=1), version int NOT NULL);
INSERT INTO ipsicol.version VALUES(1,1) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS ipsicol.regionales (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre text UNIQUE NOT NULL);
INSERT INTO ipsicol.regionales(nombre) VALUES('Bogotá'),('Cundinamarca') ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS ipsicol.inventarios (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 regional_id bigint NOT NULL REFERENCES ipsicol.regionales,
 nombre text NOT NULL CHECK(length(trim(nombre)) BETWEEN 1 AND 100),
 activo boolean NOT NULL DEFAULT true, creado_en timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS inventario_nombre ON ipsicol.inventarios(regional_id,lower(nombre)) WHERE activo;
CREATE TABLE IF NOT EXISTS ipsicol.productos (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 inventario_id bigint NOT NULL REFERENCES ipsicol.inventarios,
 nombre text NOT NULL CHECK(length(trim(nombre)) BETWEEN 1 AND 140),
 inicial bigint NOT NULL CHECK(inicial>=0), entradas bigint NOT NULL DEFAULT 0 CHECK(entradas>=0),
 salidas bigint NOT NULL DEFAULT 0 CHECK(salidas>=0), ajustes bigint NOT NULL DEFAULT 0,
 actual bigint NOT NULL CHECK(actual BETWEEN 0 AND 2000000000),
 activo boolean NOT NULL DEFAULT true, version bigint NOT NULL DEFAULT 1,
 CHECK(actual=inicial+entradas-salidas+ajustes), CHECK(actual+salidas<=2000000000));
CREATE UNIQUE INDEX IF NOT EXISTS producto_nombre ON ipsicol.productos(inventario_id,lower(nombre)) WHERE activo;
CREATE SEQUENCE IF NOT EXISTS ipsicol.ingreso_num;
CREATE SEQUENCE IF NOT EXISTS ipsicol.salida_num;
CREATE TABLE IF NOT EXISTS ipsicol.comprobantes (
 id uuid PRIMARY KEY, tipo text NOT NULL CHECK(tipo IN ('INGRESO','SALIDA')),
 numero bigint NOT NULL CHECK(numero>0), fecha date NOT NULL,
 destino text NOT NULL, responsable text NOT NULL, ubicacion text NOT NULL DEFAULT '',
 observacion text NOT NULL DEFAULT '', creado_por text NOT NULL,
 creado_en timestamptz NOT NULL DEFAULT now(), UNIQUE(tipo,numero));
CREATE TABLE IF NOT EXISTS ipsicol.lineas (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 comprobante_id uuid NOT NULL REFERENCES ipsicol.comprobantes,
 producto_id bigint NOT NULL REFERENCES ipsicol.productos,
 inventario text NOT NULL, regional text NOT NULL, objeto text NOT NULL,
 cantidad bigint NOT NULL CHECK(cantidad BETWEEN 1 AND 2000000000),
 anulada boolean NOT NULL DEFAULT false, motivo text, anulada_por text, anulada_en timestamptz,
 UNIQUE(comprobante_id,producto_id));
CREATE INDEX IF NOT EXISTS lineas_producto ON ipsicol.lineas(producto_id);
CREATE INDEX IF NOT EXISTS comprobantes_fecha ON ipsicol.comprobantes(fecha DESC);
CREATE TABLE IF NOT EXISTS ipsicol.documentos (
 id uuid PRIMARY KEY, comprobante_id uuid NOT NULL REFERENCES ipsicol.comprobantes,
 linea_id bigint REFERENCES ipsicol.lineas ON DELETE CASCADE,
 nombre text NOT NULL, mime text NOT NULL, contenido bytea NOT NULL,
 hash text NOT NULL, creado_por text NOT NULL, creado_en timestamptz NOT NULL DEFAULT now(),
 CHECK(octet_length(contenido) BETWEEN 1 AND 5242880));
CREATE INDEX IF NOT EXISTS documentos_comprobante ON ipsicol.documentos(comprobante_id);
CREATE TABLE IF NOT EXISTS ipsicol.auditoria (
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, usuario text NOT NULL,
 accion text NOT NULL, detalle jsonb NOT NULL, fecha timestamptz NOT NULL DEFAULT now());
-- Idempotencia: un reintento del mismo formulario no duplica existencias.
CREATE TABLE IF NOT EXISTS ipsicol.operaciones (
 token uuid PRIMARY KEY, usuario text NOT NULL, accion text NOT NULL,
 huella text NOT NULL, resultado jsonb NOT NULL, creado_en timestamptz NOT NULL DEFAULT now());
-- Intentos compartidos entre sesiones/servidores; sin guardar contraseñas.
CREATE TABLE IF NOT EXISTS ipsicol.login_intentos (
 usuario text PRIMARY KEY, fallos int NOT NULL DEFAULT 0,
 ventana timestamptz NOT NULL DEFAULT now(), bloqueado_hasta timestamptz);
REVOKE ALL ON ALL TABLES IN SCHEMA ipsicol FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA ipsicol FROM PUBLIC;
COMMIT;
'''


def title_name(value, limit=140):
    value = clean(value, 'Nombre', limit)
    for i, c in enumerate(value):
        if c.isalpha():
            return value[:i] + c.upper() + value[i+1:]
    return value


def clean(value, label, limit=500):
    if not isinstance(value, str):
        raise ValueError(f'{label}: escribe un texto válido.')
    value = value.strip()
    if not value or len(value) > limit:
        raise ValueError(f'{label}: escribe entre 1 y {limit} caracteres.')
    # ReportLab usa XML; los controles no imprimibles no son admisibles.
    if any(ord(c)<32 and c not in '\n\t' for c in value):
        raise ValueError(f'{label}: contiene caracteres no válidos.')
    return value


def qty(value, zero=False):
    try:
        n = int(value)
        if isinstance(value, bool) or float(value) != n or not (0 if zero else 1) <= n <= MAX_QTY:
            raise ValueError
    except (ValueError, TypeError, OverflowError):
        raise ValueError('La cantidad debe ser un número entero válido.') from None
    return n


def state(p):
    if p['actual']==0: return '🔴 Agotado'
    base=p['inicial']+p['entradas']+p['ajustes']
    if p['actual']*5<=base: return '🟠 Bajo'
    if p['salidas']==0: return '🟢 Disponible'
    return '🟡 Con salidas'


def receipt_label(c):
    return f"Factura de {'ingreso' if c['tipo']=='INGRESO' else 'salida'} #{int(c['numero']):08d}"


def password_hash(password):
    if len(password)<12: raise ValueError('Utiliza una contraseña de al menos 12 caracteres.')
    salt=secrets.token_bytes(16)
    digest=hashlib.pbkdf2_hmac('sha256',password.encode(),salt,600000)
    return f'pbkdf2_sha256$600000${salt.hex()}${digest.hex()}'


def password_ok(password, encoded):
    try:
        algorithm,iterations,salt,digest=encoded.split('$')
        if algorithm!='pbkdf2_sha256' or not 100000<=int(iterations)<=2000000: return False
        candidate=hashlib.pbkdf2_hmac('sha256',password.encode(),bytes.fromhex(salt),int(iterations))
        return hmac.compare_digest(candidate,bytes.fromhex(digest))
    except (ValueError,TypeError): return False


def validate_document(name, data):
    if not 0<len(data)<=MAX_FILE: raise ValueError('Cada documento debe tener contenido y pesar como máximo 5 MB.')
    suffix=Path(name).suffix.lower()
    if suffix=='.pdf':
        if not data[:1024].lstrip().startswith(b'%PDF-'): raise ValueError('El documento no tiene una cabecera PDF válida.')
        return 'application/pdf'
    if suffix not in ('.png','.jpg','.jpeg','.webp'):
        raise ValueError('Adjunta un PDF o una imagen PNG, JPG o WEBP.')
    from PIL import Image
    with Image.open(io.BytesIO(data)) as im:
        if im.width*im.height>40_000_000: raise ValueError('La imagen es demasiado grande.')
        fmt=im.format
        im.verify()
    if fmt not in ('PNG','JPEG','WEBP'): raise ValueError('El contenido de la imagen no es válido.')
    return {'PNG':'image/png','JPEG':'image/jpeg','WEBP':'image/webp'}[fmt]


class Database:
    def __init__(self, pool): self.pool=pool

    @contextmanager
    def tx(self, write=False):
        from psycopg.rows import dict_row
        with self.pool.connection() as con:
            con.row_factory=dict_row
            with con.transaction():
                con.execute("SET LOCAL statement_timeout='15s'")
                con.execute("SET LOCAL lock_timeout='8s'")
                if write: con.execute('SELECT pg_advisory_xact_lock(%s)',(WRITE_LOCK,))
                yield con

    def query(self, sql, args=()):
        with self.tx() as c: return c.execute(sql,args).fetchall()

    def regions(self): return self.query('SELECT * FROM ipsicol.regionales ORDER BY id')

    def inventories(self, active=True):
        return self.query('''SELECT i.*,r.nombre regional FROM ipsicol.inventarios i
            JOIN ipsicol.regionales r ON r.id=i.regional_id WHERE (%s=false OR i.activo)
            ORDER BY r.nombre,i.nombre,i.id''',(active,))

    def products(self, inv=None, active=True):
        return self.query('''SELECT p.*,i.nombre inventario,r.nombre regional,i.activo inventario_activo
            FROM ipsicol.productos p JOIN ipsicol.inventarios i ON i.id=p.inventario_id
            JOIN ipsicol.regionales r ON r.id=i.regional_id
            WHERE (%s=false OR (p.activo AND i.activo)) AND (%s::bigint IS NULL OR i.id=%s)
            ORDER BY i.nombre,p.nombre,p.id''',(active,inv,inv))

    @staticmethod
    def audit(c,user,action,data):
        from psycopg.types.json import Jsonb
        c.execute('INSERT INTO ipsicol.auditoria(usuario,accion,detalle) VALUES(%s,%s,%s)',(user,action,Jsonb(data)))

    @contextmanager
    def operation(self, user, token, action, payload):
        from psycopg.types.json import Jsonb
        fingerprint=hashlib.sha256(json.dumps(payload,sort_keys=True,default=str).encode()).hexdigest()
        with self.tx(True) as c:
            old=c.execute('SELECT * FROM ipsicol.operaciones WHERE token=%s',(uuid.UUID(str(token)),)).fetchone()
            if old:
                if old['usuario']!=user or old['accion']!=action or old['huella']!=fingerprint:
                    raise ValueError('Esta operación ya fue procesada con otros datos. Actualiza la página.')
                yield c,old['resultado'],True
            else:
                result={}
                yield c,result,False
                c.execute('INSERT INTO ipsicol.operaciones(token,usuario,accion,huella,resultado) VALUES(%s,%s,%s,%s,%s)',
                          (uuid.UUID(str(token)),user,action,fingerprint,Jsonb(result)))
                self.audit(c,user,action,result)

    @staticmethod
    def insert_document(c, receipt_id, line_id, upload, user):
        if upload is None: return
        name,data=upload
        mime=validate_document(name,data)
        name=clean(Path(name.replace('\\','/')).name,'Nombre del documento',220)
        if line_id is not None and not c.execute('SELECT 1 FROM ipsicol.lineas WHERE id=%s AND comprobante_id=%s',
                                               (line_id,receipt_id)).fetchone():
            raise ValueError('El producto ya no pertenece a esta factura.')
        c.execute('''INSERT INTO ipsicol.documentos(id,comprobante_id,linea_id,nombre,mime,contenido,hash,creado_por)
                     VALUES(%s,%s,%s,%s,%s,%s,%s,%s)''',
                  (uuid.uuid4(),receipt_id,line_id,name,mime,data,hashlib.sha256(data).hexdigest(),user))

    @staticmethod
    def insert_receipt(c, kind, day, dest, responsible, location, note, user):
        rid=uuid.uuid4()
        seq='ipsicol.ingreso_num' if kind=='INGRESO' else 'ipsicol.salida_num'
        number=c.execute('SELECT nextval(%s::regclass) n',(seq,)).fetchone()['n']
        c.execute('''INSERT INTO ipsicol.comprobantes(id,tipo,numero,fecha,destino,responsable,ubicacion,observacion,creado_por)
                     VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s)''',
                  (rid,kind,number,day,clean(dest,'Origen / Destino'),clean(responsible,'Responsable'),location,note[:1000],user))
        return rid,number

    @staticmethod
    def insert_line(c,rid,p,n):
        c.execute('''INSERT INTO ipsicol.lineas(comprobante_id,producto_id,inventario,regional,objeto,cantidad)
                     VALUES(%s,%s,%s,%s,%s,%s)''',(rid,p['id'],p['inventario'],p['regional'],p['nombre'],n))

    def receive(self,user,token,inv_id,new_name,region,lines,day,origin,responsible,note='',upload=None):
        """Cada línea: {'name': nombre nuevo, 'quantity': n} o {'product_id': id, 'quantity': n}."""
        if not lines or len(lines)>300: raise ValueError('Añade entre 1 y 300 productos.')
        payload=[inv_id,new_name,region,lines,day,origin,responsible,note,upload_digest(upload)]
        with self.operation(user,token,'INGRESO',payload) as (c,result,done):
            if done: return result
            if inv_id is None:
                inv_id=c.execute('INSERT INTO ipsicol.inventarios(nombre,regional_id) VALUES(%s,%s) RETURNING id',
                                 (title_name(new_name,100),region)).fetchone()['id']
            inv=c.execute('''SELECT i.*,r.nombre regional FROM ipsicol.inventarios i JOIN ipsicol.regionales r
                             ON r.id=i.regional_id WHERE i.id=%s AND i.activo''',(inv_id,)).fetchone()
            if not inv: raise ValueError('El inventario ya no está activo.')
            rid,number=self.insert_receipt(c,'INGRESO',day,origin,responsible,'',note,user)
            used=set()
            for line in lines:
                n=qty(line['quantity']);pid=line.get('product_id')
                if pid is None:
                    name=title_name(line['name'])
                    pid=c.execute('''INSERT INTO ipsicol.productos(inventario_id,nombre,inicial,actual)
                                     VALUES(%s,%s,%s,%s) RETURNING id''',(inv_id,name,n,n)).fetchone()['id']
                else:
                    p=c.execute('SELECT * FROM ipsicol.productos WHERE id=%s AND inventario_id=%s AND activo',
                                (pid,inv_id)).fetchone()
                    if not p: raise ValueError('Un producto fue eliminado o no pertenece al inventario.')
                    name=p['nombre']
                    c.execute('UPDATE ipsicol.productos SET entradas=entradas+%s,actual=actual+%s,version=version+1 WHERE id=%s',(n,n,pid))
                if pid in used: raise ValueError('El producto está repetido en el ingreso; combina sus cantidades.')
                used.add(pid)
                self.insert_line(c,rid,dict(id=pid,nombre=name,inventario=inv['nombre'],regional=inv['regional']),n)
            self.insert_document(c,rid,None,upload,user)
            result.update(id=str(rid),numero=number,tipo='INGRESO',inventario_id=inv_id)
        return result

    def issue(self,user,token,lines,day,destination,responsible,location,note='',upload=None):
        if location not in UBICACIONES: raise ValueError('Selecciona una ubicación válida.')
        if not lines or len(lines)>300: raise ValueError('Añade entre 1 y 300 productos.')
        grouped={}
        for line in lines:
            pid=int(line['product_id']);grouped[pid]=qty(grouped.get(pid,0)+qty(line['quantity']))
        payload=[grouped,day,destination,responsible,location,note,upload_digest(upload)]
        with self.operation(user,token,'SALIDA',payload) as (c,result,done):
            if done: return result
            rid,number=self.insert_receipt(c,'SALIDA',day,destination,responsible,location,note,user)
            for pid,n in sorted(grouped.items()):
                p=c.execute('''SELECT p.*,i.nombre inventario,r.nombre regional FROM ipsicol.productos p
                     JOIN ipsicol.inventarios i ON i.id=p.inventario_id JOIN ipsicol.regionales r ON r.id=i.regional_id
                     WHERE p.id=%s AND p.activo AND i.activo FOR UPDATE OF p''',(pid,)).fetchone()
                if not p: raise ValueError('Un producto fue eliminado. Actualiza la lista de entrega.')
                if n>p['actual']: raise ValueError(f"{p['nombre']}: quedan {p['actual']} unidades; solicitaste {n}.")
                c.execute('UPDATE ipsicol.productos SET actual=actual-%s,salidas=salidas+%s,version=version+1 WHERE id=%s',(n,n,pid))
                self.insert_line(c,rid,p,n)
            self.insert_document(c,rid,None,upload,user)
            result.update(id=str(rid),numero=number,tipo='SALIDA')
        return result

    def edit_product(self,user,token,pid,version,name,stock,reason):
        stock=qty(stock,True);name=title_name(name);reason=clean(reason,'Motivo de la corrección')
        with self.operation(user,token,'CORRECCION',[pid,version,name,stock,reason]) as (c,result,done):
            if done: return result
            p=c.execute('SELECT * FROM ipsicol.productos WHERE id=%s AND activo FOR UPDATE',(pid,)).fetchone()
            if not p or p['version']!=version: raise ValueError('El producto cambió. Actualiza y revisa la cantidad antes de corregirlo.')
            # Debe poder devolverse todo lo entregado sin desbordar el límite.
            if stock+p['salidas']>MAX_QTY: raise ValueError('La cantidad corregida supera el límite permitido.')
            c.execute('''UPDATE ipsicol.productos SET nombre=%s,actual=%s,ajustes=ajustes+%s,version=version+1 WHERE id=%s''',
                      (name,stock,stock-p['actual'],pid))
            result.update(producto=pid,antes=p['actual'],despues=stock,nombre_antes=p['nombre'],nombre=name,motivo=reason)
        return result

    def archive(self,user,token,inv_id,pid=None):
        with self.operation(user,token,'ELIMINAR_INVENTARIO' if pid is None else 'ELIMINAR_PRODUCTO',[inv_id,pid]) as (c,result,done):
            if done: return result
            if pid is None:
                c.execute('UPDATE ipsicol.inventarios SET activo=false WHERE id=%s',(inv_id,))
                c.execute('UPDATE ipsicol.productos SET activo=false,version=version+1 WHERE inventario_id=%s',(inv_id,))
            else:
                c.execute('UPDATE ipsicol.productos SET activo=false,version=version+1 WHERE id=%s AND inventario_id=%s',(pid,inv_id))
            result.update(inventario=inv_id,producto=pid)
        return result

    def cancel(self,user,token,rid,line_ids,reason):
        reason=clean(reason,'Motivo de devolución')
        ids=sorted(set(map(int,line_ids)))
        if not ids: raise ValueError('Selecciona al menos un producto vigente.')
        with self.operation(user,token,'DEVOLVER',[str(rid),ids,reason]) as (c,result,done):
            if done: return result
            lines=c.execute('''SELECT l.* FROM ipsicol.lineas l JOIN ipsicol.comprobantes c ON c.id=l.comprobante_id
                    WHERE l.comprobante_id=%s AND l.id=ANY(%s) AND c.tipo='SALIDA' FOR UPDATE OF l''',(rid,ids)).fetchall()
            if len(lines)!=len(ids) or any(l['anulada'] for l in lines):
                raise ValueError('Alguna salida ya fue anulada o eliminada. Actualiza Consultas.')
            for l in lines:
                # Recuperar sin colisión de nombres si se creó un sustituto.
                p=c.execute('SELECT * FROM ipsicol.productos WHERE id=%s',(l['producto_id'],)).fetchone()
                inv=c.execute('SELECT * FROM ipsicol.inventarios WHERE id=%s',(p['inventario_id'],)).fetchone()
                if not inv['activo']:
                    collision=c.execute('SELECT 1 FROM ipsicol.inventarios WHERE activo AND regional_id=%s AND lower(nombre)=lower(%s)',(inv['regional_id'],inv['nombre'])).fetchone()
                    name=f"{inv['nombre'][:65]} (recuperado {uuid.uuid4().hex[:8]})" if collision else inv['nombre']
                    c.execute('UPDATE ipsicol.inventarios SET activo=true,nombre=%s WHERE id=%s',(name,inv['id']))
                name=p['nombre']
                if not p['activo']:
                    collision=c.execute('SELECT 1 FROM ipsicol.productos WHERE activo AND inventario_id=%s AND lower(nombre)=lower(%s)',(inv['id'],name)).fetchone()
                    if collision: name=f"{name[:105]} (recuperado {uuid.uuid4().hex[:8]})"
                c.execute('''UPDATE ipsicol.productos SET actual=actual+%s,salidas=salidas-%s,
                             activo=true,nombre=%s,version=version+1 WHERE id=%s''',(l['cantidad'],l['cantidad'],name,p['id']))
                c.execute('UPDATE ipsicol.lineas SET anulada=true,motivo=%s,anulada_por=%s,anulada_en=now() WHERE id=%s',(reason,user,l['id']))
            result.update(lineas=ids,unidades=sum(l['cantidad'] for l in lines),motivo=reason)
        return result

    def purge(self,user,token,rid,ids):
        ids=sorted(set(map(int,ids)))
        if not ids: raise ValueError('Selecciona salidas anuladas.')
        with self.operation(user,token,'BORRAR_ANULADAS',[str(rid),ids]) as (c,result,done):
            if done: return result
            rows=c.execute('''SELECT l.* FROM ipsicol.lineas l JOIN ipsicol.comprobantes c ON c.id=l.comprobante_id
                WHERE l.id=ANY(%s) AND l.comprobante_id=%s AND c.tipo='SALIDA' AND l.anulada''',(ids,rid)).fetchall()
            if len(rows)!=len(ids): raise ValueError('Solo se pueden borrar las salidas anuladas seleccionadas.')
            c.execute('DELETE FROM ipsicol.lineas WHERE id=ANY(%s)',(ids,))
            # Cabecera y número reservados; documentos de toda la entrega conservados.
            result.update(comprobante=str(rid),lineas=ids)
        return result

    def attach(self,user,token,rid,line_id,upload):
        if not upload: raise ValueError('Elige un archivo.')
        with self.operation(user,token,'ADJUNTAR',[str(rid),line_id,upload_digest(upload)]) as (c,result,done):
            if done: return result
            self.insert_document(c,rid,line_id,upload,user)
            result.update(comprobante=str(rid),linea=line_id,archivo=upload[0])
        return result

    def receipt(self,rid):
        with self.tx() as c:
            c.execute('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ')
            head=c.execute('SELECT * FROM ipsicol.comprobantes WHERE id=%s',(rid,)).fetchone()
            if not head: raise ValueError('El comprobante no existe.')
            lines=c.execute('SELECT * FROM ipsicol.lineas WHERE comprobante_id=%s ORDER BY id',(rid,)).fetchall()
            docs=c.execute('SELECT id,linea_id,nombre,mime,creado_en FROM ipsicol.documentos WHERE comprobante_id=%s ORDER BY creado_en',(rid,)).fetchall()
            return head,lines,docs

    def history(self, filters, page=0):
        where=[];args=[]
        for expression,key in [('c.tipo=%s','tipo'),('c.fecha>=%s','desde'),('c.fecha<=%s','hasta'),
                               ('c.numero=%s','numero'),('c.ubicacion=%s','ubicacion')]:
            if filters.get(key) is not None: where.append(expression);args.append(filters[key])
        line_where=[]
        for expression,key in [('l.regional=%s','regional'),('p.inventario_id=%s','inventario'),
                               ('l.producto_id=%s','producto'),('l.anulada=%s','anulada')]:
            if filters.get(key) is not None:
                line_where.append(expression)
                args.append(filters[key])
        if line_where:
            where.append('EXISTS(SELECT 1 FROM ipsicol.lineas l JOIN ipsicol.productos p ON p.id=l.producto_id WHERE l.comprobante_id=c.id AND '+ ' AND '.join(line_where)+')')
        clause=' WHERE '+' AND '.join(where) if where else ''
        with self.tx() as c:
            c.execute('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ')
            count=c.execute('SELECT count(*) n FROM ipsicol.comprobantes c'+clause,args).fetchone()['n']
            rows=c.execute('''SELECT c.*,(SELECT count(*) FROM ipsicol.lineas l WHERE l.comprobante_id=c.id) productos,
                (SELECT count(*) FROM ipsicol.lineas l WHERE l.comprobante_id=c.id AND l.anulada) anuladas,
                (SELECT coalesce(sum(cantidad),0) FROM ipsicol.lineas l WHERE l.comprobante_id=c.id AND NOT l.anulada) unidades
                FROM ipsicol.comprobantes c'''+clause+' ORDER BY c.fecha DESC,c.creado_en DESC LIMIT 50 OFFSET %s',args+[page*50]).fetchall()
        return rows,count

    def login_attempt(self,username,password,users):
        # Solo usuarios configurados: evita poblar la tabla con nombres arbitrarios.
        encoded=users.get(username,{}).get('password_hash','')
        if not encoded:
            hashlib.pbkdf2_hmac('sha256',password.encode(),b'ipsicol-inexistente',600000)
            return False
        with self.tx() as c:
            c.execute('INSERT INTO ipsicol.login_intentos(usuario) VALUES(%s) ON CONFLICT DO NOTHING',(username,))
            r=c.execute('SELECT * FROM ipsicol.login_intentos WHERE usuario=%s FOR UPDATE',(username,)).fetchone()
            now=datetime.now(BOGOTA)
            if r['bloqueado_hasta'] and r['bloqueado_hasta']>now: return False
            ok=password_ok(password,encoded)
            count=0 if ok or r['ventana']<now-timedelta(minutes=15) else r['fallos']
            if not ok: count+=1
            c.execute('UPDATE ipsicol.login_intentos SET fallos=%s,ventana=%s,bloqueado_hasta=%s WHERE usuario=%s',
                      (count,now if count<=1 else r['ventana'],now+timedelta(minutes=15) if count>=5 else None,username))
            return ok


def upload_digest(upload):
    return [upload[0],hashlib.sha256(upload[1]).hexdigest()] if upload else None


def make_pdf(title,subtitle,metadata,headers,rows,sign_store=False,sign_receiver=False,note=''):
    from reportlab.lib import colors
    from reportlab.lib.enums import TA_CENTER
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,KeepTogether
    import reportlab
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    font_dir=Path(reportlab.__file__).parent / 'fonts'
    if 'IPSBodyFont' not in pdfmetrics.getRegisteredFontNames():
        pdfmetrics.registerFont(TTFont('IPSBodyFont',str(font_dir/'Vera.ttf')))
        pdfmetrics.registerFont(TTFont('IPSBoldFont',str(font_dir/'VeraBd.ttf')))
    buffer=io.BytesIO();styles=getSampleStyleSheet()
    body=ParagraphStyle('IPSBody',fontName='IPSBodyFont',fontSize=10.5,leading=14,spaceAfter=5)
    heading=ParagraphStyle('IPSTitle',fontName='IPSBoldFont',fontSize=18,leading=22,textColor=colors.HexColor('#AF126C'))
    center=ParagraphStyle('IPSCenter',parent=body,alignment=TA_CENTER)
    table_heading=ParagraphStyle('IPSTableHeading',parent=center,fontSize=9.5,leading=12)
    def p(text,style=body): return Paragraph(escape(str(text)).replace('\n','<br/>'),style)
    doc=SimpleDocTemplate(buffer,pagesize=A4,rightMargin=36,leftMargin=36,topMargin=32,bottomMargin=40,
                          title=title,author='IPSICOL')
    logo=Image(io.BytesIO(base64.b64decode(LOGO_PNG_BASE64)),width=75,height=75,kind='proportional')
    header=Table([[logo,[p('IPSICOL',heading),p(title,heading),p(subtitle)]]],colWidths=[90,433])
    header.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE')]))
    story=[header,Spacer(1,14)]
    for k,v in metadata: story.append(p(f'{k}: {v}'))
    story.append(Spacer(1,12))
    count=len(headers)
    widths=([32,90,94,121,69,65,52] if count==7 else [32,102,95,154,60,80] if count==6 else [523/count]*count)
    table=Table([[p(h,table_heading) for h in headers]]+[[p(v,center) for v in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='CENTER')
    table.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#F4DCE9')),
        ('VALIGN',(0,0),(-1,-1),'MIDDLE'),('GRID',(0,0),(-1,-1),0.4,colors.HexColor('#D7C9D1')),
        ('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),
        ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#FCF7FA')])]))
    story.append(table)
    if note: story.extend([Spacer(1,12),p(note)])
    names=[]
    if sign_store: names.append('Responsable de almacén')
    if sign_receiver: names.append('Quien recibe')
    if names:
        signatures=Table([[p('________________________________',center) for _ in names],
                          [p(n,center) for n in names]],colWidths=[523/len(names)]*len(names))
        story.append(KeepTogether([Spacer(1,50),signatures]))
    def footer(canvas,document):
        canvas.saveState();canvas.setFont('IPSBodyFont',9);canvas.setFillColor(colors.HexColor('#65535E'))
        canvas.drawString(36,23,'IPSICOL · Constancia interna de inventario')
        canvas.drawRightString(A4[0]-36,23,f'Página {document.page}');canvas.restoreState()
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
    return buffer.getvalue()


def receipt_pdf(head,lines,sign_store=False,sign_receiver=False):
    rows=[[i,l['inventario'],l['regional'],l['objeto'],l['cantidad'],'Anulada' if l['anulada'] else 'Vigente'] for i,l in enumerate(lines,1)]
    metadata=[('Fecha',head['fecha'].strftime('%d/%m/%Y')),('Origen' if head['tipo']=='INGRESO' else 'Destino',head['destino']),
              ('Responsable',head['responsable']),('Ubicación',head['ubicacion'] or 'No aplica'),('Registrado por',head['creado_por'])]
    note=head.get('observacion','')
    canceled=[f"{l['objeto']}: {l['motivo']}" for l in lines if l['anulada']]
    if canceled: note+='\nDevoluciones: '+'; '.join(canceled)
    if not lines: note+='\nLas líneas de esta factura fueron eliminadas después de su anulación.'
    return make_pdf(receipt_label(head),'Constancia de movimiento',metadata,
                    ['N°','Inventario','Regional','Producto','Cantidad','Estado'],rows,sign_store,sign_receiver,note)


def inventory_pdf(inv,products,sign_store=False,sign_receiver=False):
    rows=[[i,inv['nombre'],inv['regional'],p['nombre'],p['inicial']+p['entradas'],p['salidas'],p['actual']] for i,p in enumerate(products,1)]
    return make_pdf('Constancia de inventario',inv['nombre'],
        [('Regional',inv['regional']),('Creado el',inv['creado_en'].astimezone(BOGOTA).strftime('%d/%m/%Y %H:%M')),
         ('Existencias consultadas el',datetime.now(BOGOTA).strftime('%d/%m/%Y %H:%M'))],
        ['N°','Inventario','Regional','Producto','Ingresadas','Salidas netas','Actual'],rows,sign_store,sign_receiver,
        'Las existencias actuales incluyen correcciones registradas. Los ingresos originales se consultan por su factura.')


def web_app():
    import streamlit as st
    import pandas as pd
    from psycopg_pool import ConnectionPool
    from psycopg.rows import dict_row
    import psycopg
    st.set_page_config(page_title=APP_NAME,page_icon='📦',layout='wide')
    st.markdown('''<style>
    :root {font-size:17px;} .stApp {background:#FAF7FA;}
    [data-testid="stSidebar"] {background:#F7E6F0;}
    h1,h2,h3 {color:#AD126A;} div[data-testid="stMetric"] {background:white;border-radius:12px;padding:16px;}
    .ips-table {overflow:auto;max-height:580px;border:1px solid #DECBD5;border-radius:8px;background:white;}
    .ips-table table {width:100%;border-collapse:collapse;font-size:17px;}
    .ips-table th {background:#F4DCE9;position:sticky;top:0;z-index:1;}
    .ips-table th,.ips-table td {text-align:center!important;padding:12px;border-bottom:1px solid #EADFE5;}
    .ips-table tr:nth-child(even){background:#FCF8FA;} label,p {font-size:17px;}
    </style>''',unsafe_allow_html=True)

    try:
        cfg=dict(st.secrets['postgres']);users={k:dict(v) for k,v in st.secrets['users'].items()}
    except (KeyError,FileNotFoundError):
        st.title(APP_NAME)
        st.info('Falta configurar la conexión y los usuarios. Sigue GUIA.md y copia secrets.example.toml en Secrets de Streamlit.')
        st.stop()
    if not users or any(v.get('role') not in ('admin','editor','consulta') or not v.get('password_hash','').startswith('pbkdf2_sha256$') for v in users.values()):
        st.error('Revisa los usuarios, sus roles y sus hashes de contraseña en Secrets.');st.stop()

    @st.cache_resource(show_spinner=False)
    def get_db(config):
        if config.get('sslmode','require') not in ('require','verify-ca','verify-full'):
            raise ValueError('La conexión en la nube requiere SSL.')
        pool=ConnectionPool(conninfo='',kwargs={**config,'connect_timeout':10,'prepare_threshold':None,'row_factory':dict_row},
                            min_size=0,max_size=4,timeout=12,max_idle=60,open=True)
        return Database(pool)
    db=get_db(cfg)

    def auth(edit=False,admin=False):
        session=st.session_state.get('auth')
        user=users.get(session['user']) if session else None
        valid=user and session['fingerprint']==hashlib.sha256(user['password_hash'].encode()).hexdigest() and time.time()<session['expires']
        if not valid:
            if session:
                st.session_state.clear();st.rerun()
            st.stop()
        if admin and user['role']!='admin' or edit and user['role']=='consulta':
            st.error('Tu usuario no tiene permiso para esta acción.');st.stop()
        return session['user']

    if not st.session_state.get('auth'):
        left,center,right=st.columns([1,2,1])
        with center:
            st.image(base64.b64decode(LOGO_PNG_BASE64),width=150)
            st.title('Inventarios IPSICOL')
            st.write('Inicia sesión para consultar y gestionar los inventarios.')
            with st.form('login',clear_on_submit=True):
                username=st.text_input('Usuario',max_chars=80).strip().lower()
                password=st.text_input('Contraseña',type='password',max_chars=256)
                pressed=st.form_submit_button('Ingresar',type='primary',width='stretch')
            if pressed:
                # Límite también para nombres desconocidos en esta sesión.
                now=time.time();recent=[x for x in st.session_state.get('login_times',[]) if now-x<60]
                st.session_state.login_times=recent+[now]
                if len(recent)>=5:
                    st.error('Espera un minuto antes de volver a intentar.');st.stop()
                try:
                    ok=db.login_attempt(username,password,users)
                except psycopg.errors.UndefinedTable:
                    st.error('Falta inicializar la base de datos. Ejecuta schema.sql en el SQL Editor de Supabase.');st.stop()
                except Exception:
                    st.error('No fue posible conectar. Revisa la conexión, las credenciales y que el proyecto esté activo.');st.stop()
                if ok:
                    st.session_state.clear()
                    st.session_state.auth=dict(user=username,fingerprint=hashlib.sha256(users[username]['password_hash'].encode()).hexdigest(),expires=now+8*3600)
                    st.rerun()
                st.error('Acceso no autorizado. Revisa usuario y contraseña; tras 5 intentos fallidos, espera 15 minutos.')
        st.stop()

    user=auth();role=users[user]['role'];can_edit=role in ('admin','editor')
    with st.sidebar:
        st.image(base64.b64decode(LOGO_PNG_BASE64),width=160)
        st.title('IPSICOL')
        st.write(f"{users[user].get('name',user)} · {role}")
        page=st.radio('Navegación',['Resumen','Inventarios','Ingresos','Salidas','Consultas'])
        if st.button('Actualizar datos',width='stretch'):
            st.session_state.pop('edit_snapshot',None);st.rerun()
        st.caption('Tablas: actualización automática cada 10 segundos. Fechas y horas: Bogotá/Colombia.')
        if st.button('Cerrar sesión',width='stretch'):
            st.session_state.clear();st.rerun()

    def show_table(rows):
        if not rows: st.info('No hay registros para mostrar.');return
        # Escape obligatorio: nombres/destinos son texto del usuario, nunca HTML.
        keys=list(rows[0]);th=''.join('<th>'+escape(str(k))+'</th>' for k in keys)
        body=''.join('<tr>'+''.join('<td>'+escape(str(row.get(k,'')))+'</td>' for k in keys)+'</tr>' for row in rows)
        st.markdown('<div class="ips-table"><table><thead><tr>'+th+'</tr></thead><tbody>'+body+'</tbody></table></div>',unsafe_allow_html=True)

    def token(key):
        if 'token_'+key not in st.session_state: st.session_state['token_'+key]=str(uuid.uuid4())
        return st.session_state['token_'+key]

    def act(key,fn,admin=False):
        auth(edit=True,admin=admin)
        try:
            with st.spinner('Guardando…'): result=fn(token(key))
        except ValueError as exc: st.error(str(exc));return
        except psycopg.errors.UniqueViolation: st.error('Ya existe un nombre igual en esa regional o inventario. Revisa los productos repetidos.');return
        except psycopg.errors.CheckViolation: st.error('La cantidad supera el límite permitido o dejaría existencias inválidas.');return
        except Exception:
            logging.exception('Operación fallida en %s',key)
            st.error('No se confirmó la operación. Comprueba la conexión y vuelve a intentarlo con los mismos datos; el sistema evita duplicados.');return
        st.session_state.pop('token_'+key,None)
        st.session_state.flash='Operación guardada correctamente.'
        if isinstance(result,dict) and result.get('tipo') in ('INGRESO','SALIDA'):
            st.session_state.last_receipt=result['id'];st.session_state.flash=receipt_label(result)+' guardada.'
            st.session_state.cart=[];st.session_state.entry_generation=st.session_state.get('entry_generation',0)+1
        st.session_state.pop('edit_snapshot',None)
        st.rerun()

    def upload_widget(key):
        return st.file_uploader('Factura o autorización (opcional, PDF/PNG/JPG/WEBP, máximo 5 MB)',
                                type=['pdf','png','jpg','jpeg','webp'],key=key)

    def upload_value(item): return (item.name,item.getvalue()) if item else None
    def inv_label(i): return f"{i['nombre']} ({i['regional']}) · #{i['id']}"+(' [Eliminado]' if not i['activo'] else '')
    def product_label(p): return f"{p['nombre']} · {p['inventario']} ({p['regional']}) · #{p['id']}"

    def inv_select(label,key,active=True,allow_all=False):
        values=db.inventories(active)
        mapping={i['id']:i for i in values}
        options=([None] if allow_all else [])+list(mapping)
        if not options: st.info('Primero crea un inventario desde Resumen.');return None
        value=st.selectbox(label,options,format_func=lambda x:'Todos' if x is None else inv_label(mapping[x]),key=key)
        return mapping.get(value)

    def signature_options(key):
        st.write('Campos de firma para el PDF')
        a,b=st.columns(2)
        return a.checkbox('Responsable de almacén',key=key+'_almacen'),b.checkbox('Quien recibe',key=key+'_recibe')

    def download_receipt(rid,key):
        head,lines,_=db.receipt(rid)
        st.subheader(receipt_label(head))
        a,b=signature_options(key)
        st.download_button('Descargar PDF para imprimir',receipt_pdf(head,lines,a,b),
                           file_name=f"{head['tipo'].lower()}_{head['numero']:08d}.pdf",mime='application/pdf',key=key+'_pdf')
        st.caption('Abre el PDF descargado y elige Imprimir (Ctrl+P). Es una constancia interna, no una factura electrónica fiscal.')

    def creation_form():
        auth(edit=True)
        regions=db.regions();mapping={r['id']:r['nombre'] for r in regions}
        gen=st.session_state.get('entry_generation',0)
        with st.form('create_inventory_'+str(gen)):
            a,b=st.columns(2)
            name=a.text_input('Nombre del inventario',max_chars=100)
            region=b.selectbox('Regional',list(mapping),format_func=mapping.get)
            st.caption('Escribe los productos iniciales. Puedes añadir filas al final de la tabla.')
            data=st.data_editor(pd.DataFrame({'Objeto':[''],'Cantidad':[1]}),num_rows='dynamic',hide_index=True,
                width='stretch',column_config={'Objeto':st.column_config.TextColumn(required=True,max_chars=140),
                'Cantidad':st.column_config.NumberColumn(min_value=1,max_value=MAX_QTY,step=1,required=True)})
            a,b=st.columns(2);day=a.date_input('Fecha del ingreso',value=datetime.now(BOGOTA).date());origin=b.text_input('Origen / Proveedor',value='Inventario inicial')
            responsible=st.text_input('Responsable del ingreso');note=st.text_area('Observaciones',max_chars=1000)
            uploaded=upload_widget('create_upload_'+str(gen))
            save=st.form_submit_button('Crear inventario y registrar ingreso',type='primary')
        if save:
            lines=[{'name':r['Objeto'] if not pd.isna(r['Objeto']) else '', 'quantity':r['Cantidad']}
                   for r in data.to_dict('records') if not pd.isna(r['Cantidad']) or (not pd.isna(r['Objeto']) and r['Objeto'])]
            act('create_inventory',lambda t:db.receive(user,t,None,name,region,lines,day,origin,responsible,note,upload_value(uploaded)))

    @st.fragment(run_every='10s')
    def inventory_table(inv_id):
        auth()
        products=db.products(inv_id)
        show_table([{'Objeto':p['nombre'],'Cantidad inicial':p['inicial'],'Ingresos posteriores':p['entradas'],
                     'Salidas netas':p['salidas'],'Correcciones':p['ajustes'],'Cantidad actual':p['actual'],'Estado':state(p)} for p in products])
        st.caption('Actualizado: '+datetime.now(BOGOTA).strftime('%H:%M:%S'))

    @st.fragment(run_every='10s')
    def summary(inv_id):
        auth();products=db.products(inv_id);invs=db.inventories()
        a,b,c,d=st.columns(4)
        a.metric('Inventarios',1 if inv_id else len(invs));b.metric('Productos',len(products))
        c.metric('Agotados',sum(p['actual']==0 for p in products))
        d.metric('Bajos',sum('Bajo' in state(p) for p in products))
        low=[p for p in products if p['actual']==0 or 'Bajo' in state(p)]
        st.subheader('Productos que requieren atención')
        show_table([{'Inventario':p['inventario'],'Regional':p['regional'],'Producto':p['nombre'],'Disponible':p['actual'],'Estado':state(p)} for p in low])

    @st.fragment(run_every='10s')
    def live_history(filters,page_index):
        auth();rows,count=db.history(filters,page_index)
        show_table([{'Factura':receipt_label(c),'Fecha':str(c['fecha']),'Destino / Origen':c['destino'],'Responsable':c['responsable'],
                    'Productos':c['productos'],'Unidades vigentes':c['unidades'],'Anuladas':c['anuladas']} for c in rows])
        st.caption(f'{count} facturas · Página {page_index+1} · Actualizado: '+datetime.now(BOGOTA).strftime('%H:%M:%S'))

    if st.session_state.get('flash'): st.success(st.session_state.pop('flash'))
    st.title(page)
    if page=='Resumen':
        inv=inv_select('Resumen del inventario','summary_inv',allow_all=True)
        summary(inv['id'] if inv else None)
        if can_edit:
            with st.expander('Crear nuevo inventario',expanded=not db.inventories()): creation_form()
        if st.session_state.get('last_receipt'):
            with st.expander('Imprimir último ingreso o salida',expanded=True): download_receipt(st.session_state.last_receipt,'last')

    elif page=='Inventarios':
        inv=inv_select('Inventario','inventory_selected')
        if not inv: st.stop()
        inventory_table(inv['id'])
        with st.expander('Imprimir constancia del inventario'):
            a,b=signature_options('inventory')
            st.download_button('Descargar constancia PDF',inventory_pdf(inv,db.products(inv['id']),a,b),
                               file_name=f"inventario_{inv['id']}.pdf",mime='application/pdf')
        if can_edit:
            with st.expander('Corregir nombre o cantidad de un producto'):
                products=db.products(inv['id']);mapping={p['id']:p for p in products}
                if products:
                    pid=st.selectbox('Producto a corregir',list(mapping),format_func=lambda x:mapping[x]['nombre'],key='edit_product')
                    snap=st.session_state.get('edit_snapshot')
                    if not snap or snap['id']!=pid:
                        st.session_state.edit_snapshot=dict(mapping[pid]);snap=st.session_state.edit_snapshot
                    if st.button('Recargar producto antes de editar'):
                        st.session_state.pop('edit_snapshot',None);st.rerun()
                    with st.form(f"edit_{pid}_{snap['version']}"):
                        name=st.text_input('Nombre corregido',value=snap['nombre'],max_chars=140)
                        stock=st.number_input('Cantidad actual corregida',min_value=0,max_value=MAX_QTY,value=snap['actual'],step=1)
                        reason=st.text_input('Motivo de la corrección',max_chars=500)
                        st.caption('Para registrar nuevas compras, utiliza Ingresos. Las correcciones quedan en auditoría.')
                        save=st.form_submit_button('Guardar corrección')
                    if save: act('edit',lambda t:db.edit_product(user,t,pid,snap['version'],name,stock,reason))
            with st.expander('Eliminar producto o inventario'):
                options={p['id']:p['nombre'] for p in db.products(inv['id'])}
                scope=st.radio('Qué deseas eliminar',['Un producto','Inventario completo'],horizontal=True)
                pid=st.selectbox('Producto',list(options),format_func=options.get) if scope=='Un producto' and options else None
                st.write('Se retira de la gestión activa y se conserva su historial. Una devolución puede recuperarlo.')
                confirm=st.checkbox('Confirmo que deseo eliminar la selección',key='archive_confirm')
                if st.button('Eliminar selección',disabled=not confirm or (scope=='Un producto' and pid is None)):
                    act('archive',lambda t:db.archive(user,t,inv['id'],pid if scope=='Un producto' else None))

    elif page=='Ingresos':
        auth(edit=True)
        inv=inv_select('Inventario que recibe los productos','receive_inv')
        if not inv: st.stop()
        products=db.products(inv['id']);mapping={p['id']:p for p in products}
        labels={'Nuevo producto':None,**{f"{p['nombre']} · #{p['id']}":p['id'] for p in products}}
        gen=st.session_state.get('entry_generation',0)
        with st.form('receive_'+str(inv['id'])+'_'+str(gen)):
            st.write('Añade productos nuevos o registra unidades adicionales de productos existentes.')
            data=st.data_editor(pd.DataFrame({'Producto':['Nuevo producto'],'Nombre nuevo':[''],'Cantidad':[1]}),
                num_rows='dynamic',hide_index=True,width='stretch',
                column_config={'Producto':st.column_config.SelectboxColumn(options=list(labels),required=True),
                    'Nombre nuevo':st.column_config.TextColumn(max_chars=140),
                    'Cantidad':st.column_config.NumberColumn(min_value=1,max_value=MAX_QTY,step=1,required=True)})
            a,b=st.columns(2);day=a.date_input('Fecha de ingreso',datetime.now(BOGOTA).date());origin=b.text_input('Origen / Proveedor')
            responsible=st.text_input('Responsable del ingreso');note=st.text_area('Observaciones',max_chars=1000)
            uploaded=upload_widget('income_upload_'+str(gen))
            save=st.form_submit_button('Registrar ingreso',type='primary')
        if save:
            lines=[]
            for r in data.to_dict('records'):
                pid=labels.get(r['Producto'])
                if pid is not None: lines.append({'product_id':pid,'quantity':r['Cantidad']})
                elif not pd.isna(r['Cantidad']) or (not pd.isna(r['Nombre nuevo']) and r['Nombre nuevo']):
                    lines.append({'name':r['Nombre nuevo'] if not pd.isna(r['Nombre nuevo']) else '', 'quantity':r['Cantidad']})
            act('receive',lambda t:db.receive(user,t,inv['id'],None,None,lines,day,origin,responsible,note,upload_value(uploaded)))
        if st.session_state.get('last_receipt'): download_receipt(st.session_state.last_receipt,'income_last')

    elif page=='Salidas':
        auth(edit=True)
        inv=inv_select('Inventario origen','exit_inv')
        if not inv: st.stop()
        st.write('Regional: **'+inv['regional']+'**')
        products=db.products(inv['id']);mapping={p['id']:p for p in products}
        st.session_state.setdefault('cart',[])
        with st.form('add_exit_line',clear_on_submit=True):
            pid=st.selectbox('Producto',list(mapping),format_func=lambda x:f"{mapping[x]['nombre']} · disponibles: {mapping[x]['actual']}") if mapping else None
            amount=st.number_input('Cantidad a entregar',min_value=1,max_value=MAX_QTY,step=1)
            add=st.form_submit_button('Añadir a la entrega',disabled=pid is None)
        if add:
            auth(edit=True)
            p=mapping[pid];existing=sum(r['quantity'] for r in st.session_state.cart if r['product_id']==pid)
            if amount+existing>p['actual']: st.error('La cantidad total supera las existencias actuales.')
            else:
                cart=st.session_state.cart
                found=next((r for r in cart if r['product_id']==pid),None)
                if found: found['quantity']+=amount
                else: cart.append(dict(product_id=pid,quantity=amount,label=product_label(p)))
                st.rerun()
        st.subheader('Productos de la entrega')
        show_table([{'Producto / Inventario':r['label'],'Cantidad':r['quantity']} for r in st.session_state.cart])
        if st.session_state.cart:
            remove=st.multiselect('Retirar productos de esta lista',range(len(st.session_state.cart)),format_func=lambda x:st.session_state.cart[x]['label'])
            if st.button('Retirar seleccionados',disabled=not remove):
                st.session_state.cart=[r for i,r in enumerate(st.session_state.cart) if i not in remove];st.rerun()
        st.caption('Puedes cambiar el inventario origen y seguir añadiendo productos a esta misma entrega.')
        with st.form('issue_metadata',clear_on_submit=False):
            a,b=st.columns(2);day=a.date_input('Fecha de salida',datetime.now(BOGOTA).date());location=b.selectbox('Ubicación',UBICACIONES)
            destination=st.text_input('Destino');responsible=st.text_input('Responsable / Quien recibe')
            note=st.text_area('Observaciones',max_chars=1000);uploaded=upload_widget('issue_upload')
            confirm=st.checkbox('He revisado los productos y las cantidades de esta entrega')
            save=st.form_submit_button('Registrar toda la entrega',type='primary')
        if save:
            if not confirm: st.error('Marca la confirmación antes de registrar.')
            else: act('issue',lambda t:db.issue(user,t,st.session_state.cart,day,destination,responsible,location,note,upload_value(uploaded)))
        if st.session_state.get('last_receipt'): download_receipt(st.session_state.last_receipt,'issue_last')

    elif page=='Consultas':
        st.session_state.setdefault('history_filters',{})
        with st.expander('Filtros de búsqueda'):
            # Selectores relacionados fuera del form para actualizar productos al cambiar inventario.
            a,b,c=st.columns(3)
            kind=a.selectbox('Tipo',['Todos','INGRESO','SALIDA'],key='f_kind')
            region=b.selectbox('Regional',['Todas',*REGIONALES],key='f_region')
            loc=c.selectbox('Ubicación',['Todas',*UBICACIONES],key='f_location')
            invs={i['id']:i for i in db.inventories(False) if region=='Todas' or i['regional']==region}
            inv_id=st.selectbox('Inventario',[None,*invs],format_func=lambda x:'Todos' if x is None else inv_label(invs[x]),key='f_inv')
            products={p['id']:p for p in db.products(inv_id,False) if region=='Todas' or p['regional']==region}
            pid=st.selectbox('Producto',[None,*products],format_func=lambda x:'Todos' if x is None else product_label(products[x]),key='f_product')
            a,b,c=st.columns(3)
            since=a.date_input('Desde',value=None,key='f_start');until=b.date_input('Hasta',value=None,key='f_end')
            status=c.selectbox('Estado',['Todos','Vigente','Anulada'],key='f_status')
            number=st.number_input('Número de factura (0 = todos)',min_value=0,step=1,key='f_number')
            a,b=st.columns(2)
            if a.button('Aplicar filtros'):
                if since and until and since>until: st.error('La fecha inicial debe ser anterior a la final.')
                else:
                    st.session_state.history_filters=dict(tipo=None if kind=='Todos' else kind,regional=None if region=='Todas' else region,
                        inventario=inv_id,producto=pid,ubicacion=None if loc=='Todas' else loc,desde=since,hasta=until,
                        numero=number or None,anulada=None if status=='Todos' else status=='Anulada')
                    st.session_state.history_page=0;st.rerun()
            if b.button('Limpiar filtros'):
                for key in list(st.session_state):
                    if key.startswith('f_'): del st.session_state[key]
                st.session_state.history_filters={};st.session_state.history_page=0;st.rerun()
        filters=st.session_state.history_filters;page_index=st.session_state.get('history_page',0)
        live_history(filters,page_index)
        rows,count=db.history(filters,page_index)
        a,b,c=st.columns([1,3,1])
        if a.button('Anterior',disabled=page_index==0): st.session_state.history_page=page_index-1;st.rerun()
        if c.button('Siguiente',disabled=(page_index+1)*50>=count): st.session_state.history_page=page_index+1;st.rerun()
        mapping={str(r['id']):r for r in rows}
        if not mapping: st.stop()
        rid=st.selectbox('Factura para consultar, imprimir o adjuntar documentos',list(mapping),format_func=lambda x:receipt_label(mapping[x]))
        head,lines,documents=db.receipt(rid)
        st.subheader(receipt_label(head))
        st.write(f"Fecha: {head['fecha']} · Responsable: {head['responsable']} · Origen/Destino: {head['destino']}")
        show_table([{'N.º línea':l['id'],'Inventario':l['inventario'],'Regional':l['regional'],'Producto':l['objeto'],
                    'Cantidad':l['cantidad'],'Estado':'Anulada' if l['anulada'] else 'Vigente','Motivo devolución':l['motivo'] or ''} for l in lines])
        with st.expander('Imprimir esta factura / constancia',expanded=True): download_receipt(rid,'receipt_print_'+rid)
        with st.expander('Facturas y documentos adjuntos',expanded=True):
            if not documents: st.write('Esta factura todavía no tiene documentos adjuntos.')
            for doc in documents:
                st.write(doc['nombre']+(' · Toda la factura' if doc['linea_id'] is None else f" · Línea #{doc['linea_id']}"))
                if st.button('Preparar descarga',key='prepare_'+str(doc['id'])):
                    auth()
                    stored=db.query('SELECT contenido FROM ipsicol.documentos WHERE id=%s AND comprobante_id=%s',(doc['id'],rid))
                    if stored: st.session_state['doc_download_'+str(doc['id'])]=bytes(stored[0]['contenido'])
                if 'doc_download_'+str(doc['id']) in st.session_state:
                    st.download_button('Descargar documento',st.session_state['doc_download_'+str(doc['id'])],doc['nombre'],doc['mime'],key='download_'+str(doc['id']))
            if can_edit:
                with st.form('attach_'+rid,clear_on_submit=True):
                    scope=st.selectbox('Adjuntar a',[None]+[l['id'] for l in lines],format_func=lambda x:'Toda la factura' if x is None else next(f"{l['objeto']} · línea #{x}" for l in lines if l['id']==x))
                    upload=upload_widget('attach_upload_'+rid)
                    add=st.form_submit_button('Guardar documento en el sistema')
                if add: act('attach_'+rid,lambda t:db.attach(user,t,rid,scope,upload_value(upload)))
        if can_edit and head['tipo']=='SALIDA':
            with st.expander('Anular / devolver productos'):
                valid={l['id']:l for l in lines if not l['anulada']}
                with st.form('return_'+rid):
                    all_lines=st.checkbox('Devolver toda la entrega vigente')
                    selected=st.multiselect('O selecciona productos individuales',list(valid),format_func=lambda x:f"{valid[x]['objeto']} · {valid[x]['cantidad']} unidades · #{x}")
                    reason=st.text_input('Motivo de devolución',max_chars=500)
                    confirmed=st.checkbox('Confirmo que estos productos regresan al inventario')
                    save=st.form_submit_button('Anular y devolver')
                if save:
                    if not confirmed: st.error('Confirma la devolución.')
                    else: act('return_'+rid,lambda t:db.cancel(user,t,rid,list(valid) if all_lines else selected,reason))
            if role=='admin':
                with st.expander('Eliminar definitivamente salidas anuladas'):
                    canceled={l['id']:l for l in lines if l['anulada']}
                    with st.form('purge_'+rid):
                        selected=st.multiselect('Salidas anuladas a eliminar',list(canceled),format_func=lambda x:f"{canceled[x]['objeto']} · #{x}")
                        confirmed=st.checkbox('Confirmo el borrado definitivo de las líneas y sus adjuntos individuales')
                        st.caption('El número de factura permanece reservado. La auditoría y los documentos de toda la factura se conservan.')
                        save=st.form_submit_button('Eliminar definitivamente')
                    if save:
                        if not confirmed: st.error('Confirma el borrado definitivo.')
                        else: act('purge_'+rid,lambda t:db.purge(user,t,rid,selected),admin=True)
        if role=='admin':
            with st.expander('Auditoría reciente'):
                logs=db.query('SELECT fecha,usuario,accion,detalle FROM ipsicol.auditoria ORDER BY id DESC LIMIT 100')
                show_table([{'Fecha':str(l['fecha'].astimezone(BOGOTA)),'Usuario':l['usuario'],'Acción':l['accion'],'Detalle':json.dumps(l['detalle'],ensure_ascii=False)} for l in logs])


def main():
    if '--hash-password' in sys.argv:
        from getpass import getpass
        password=getpass('Nueva contraseña (mínimo 12 caracteres): ')
        if password!=getpass('Repite la contraseña: '): raise ValueError('Las contraseñas no coinciden.')
        print(password_hash(password));return
    if '--export-schema' in sys.argv:
        print(SCHEMA_SQL);return
    web_app()


